class Solution {
public:
    int minOperations(vector<int>& nums) {
        int cur_flips = 0;
        for (int x : nums) {
            if ((x ^ (cur_flips % 2)) == 0) {
                cur_flips++;
            }
        }
        return cur_flips;
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int curFlips = 0;
        for (int x : nums) {
            if ((x ^ (curFlips % 2)) == 0) {
                curFlips++;
            }
        }
        return curFlips;
    }
}

var minOperations = function(nums) {
    let curFlips = 0;
    for (const x of nums) {
        if ((x ^ (curFlips % 2)) === 0) {
            curFlips++;
        }
    }
    return curFlips;
};
